    const projectPath = join(cwd, ".pi", "adaptive-thinking.json");
    await writeFile(projectPath, JSON.stringify({ toolName: "project_tool" }));

    await expect(loadConfig({ cwd, homeDir })).resolves.toEqual({
      success: true,
