 69	const acquireSettingsLock = (lockPath: string) => {
 70	  const maxAttempts = 100;
 71	  const delayMs = 20;
 72	
 73	  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
 74	    try {
 75	      return lockfile.lockSync(lockPath, { realpath: false });
 76	    } catch (error) {
 77	      const code =
 78	        typeof error === "object" && error !== null && "code" in error ? error.code : undefined;
 79	      if (code !== "ELOCKED" || attempt === maxAttempts) throw error;
 80	      sleepSync(delayMs);
 81	    }
 82	  }
 83	
