166	const formatGuidance = (
167	  config: AdaptiveThinkingConfig,
168	  currentLevel: string | undefined,
169	  validLevels: string[],
170	) => {
171	  return (
172	    config.systemPrompt.trim() +
173	    " " +
174	    (currentLevel ? `Current thinking level: ${currentLevel}. ` : "") +
175	    `Valid thinking levels for this session: ${validLevels.join(", ")}. ` +
176	    `To change the thinking level, use the \`${config.toolName}\` tool with one of the valid levels. ` +
177	    "Only call it when the task complexity justifies changing levels. " +
178	    `Do not call ${config.toolName} if the current thinking level already matches the target level. ` +
179	    `Do not call ${config.toolName} twice in a row; reassess only after new evidence from other tool calls or user input.`
180	  );
181	};
