188	    if (runtimeHandlersRegistered) return;
189	    runtimeHandlersRegistered = true;
190	
191	    pi.on("thinking_level_select", async (event) => {
192	      if (!runtime) return;
193	      runtime.currentLevel = event.level;
194	    });
195	
196	    pi.on("tool_call", async (event) => {
197	      const state = runtime;
198	      if (!state) return;
199	
200	      if (event.toolName === state.config.toolName) {
201	        state.reasoningToolCallBackToBackById.set(
202	          event.toolCallId,
203	          state.lastToolCallWasReasoningTool ?? false,
204	        );
205	        state.lastToolCallWasReasoningTool = true;
206	      } else {
207	        state.lastToolCallWasReasoningTool = false;
208	      }
209	    });
210	
211	    pi.on("before_agent_start", async (event, ctx) => beforeAgentStart(event, ctx));
212	
213	    pi.on("agent_end", async (_event, ctx) => {
214	      await resetTemporaryLevel(ctx);
215	      if (!runtime) return;
216	      runtime.lastToolCallWasReasoningTool = false;
217	      runtime.reasoningToolCallBackToBackById.clear();
218	    });
219	  };
220	
221	  const beforeAgentStart = async (
222	    event: BeforeAgentStartEvent,
223	    ctx: ExtensionContext,
224	  ): Promise<BeforeAgentStartEventResult> => {
225	    const state = runtime;
226	    if (!state) return { systemPrompt: event.systemPrompt };
227	
228	    state.lastToolCallWasReasoningTool = false;
229	    state.reasoningToolCallBackToBackById.clear();
230	
231	    const currentLevel = state.currentLevel ?? pi.getThinkingLevel();
232	    if (isThinkingLevel(currentLevel)) state.currentLevel = currentLevel;
233	
234	    const validLevels = resolveSupportedThinkingLevels(ctx.model);
235	    return {
236	      systemPrompt: appendSystemPromptBlock(
237	        event.systemPrompt,
238	        formatGuidance(state.config, state.currentLevel, validLevels),
239	      ),
240	    };
241	  };
242	
243	  const resetTemporaryLevel = async (ctx: ExtensionContext) => {
244	    const state = runtime;
245	    const resetLevel = state?.temporaryResetLevel;
246	    if (!state || !resetLevel) return;
247	
248	    try {
249	      withSessionOnlyThinkingLevelChange(() => pi.setThinkingLevel(resetLevel));
250	      state.currentLevel = resetLevel;
251	      delete state.temporaryResetLevel;
252	    } catch (error) {
253	      notify(ctx, "error", `Failed to reset thinking level: ${errorMessage(error)}`, state.config);
254	    }
255	  };
256	
257	  pi.on("session_start", async (_event, ctx) => {
258	    const configResult = await loadConfig({ cwd: ctx.cwd });
259	    if (!configResult.success) {
260	      runtime = undefined;
261	      notify(ctx, "error", configResult.error.message);
262	      return;
263	    }
264	
265	    const { config } = configResult;
266	    if (!config.enabled) {
267	      runtime = undefined;
268	      return;
269	    }
270	
271	    const initialLevel = pi.getThinkingLevel();
272	    runtime = { config, reasoningToolCallBackToBackById: new Map() };
273	    if (isThinkingLevel(initialLevel)) runtime.currentLevel = initialLevel;
274	
275	    pi.registerTool({
276	      name: config.toolName,
277	      label: "Set Thinking Level",
278	      description: config.toolDescription,
279	      promptSnippet: "Set the current Pi thinking level.",
280	      promptGuidelines: [
281	        `Use ${config.toolName} to change the thinking level when task complexity justifies a different level.`,
282	      ],
283	      parameters: ToolParameters,
284	      execute: async (toolCallId, params: ToolParameters, _signal, _onUpdate, ctx) => {
285	        const state = runtime;
286	        if (!state) return textResult("Adaptive Thinking is not enabled for this session.");
287	
288	        const level = params.level.trim();
289	        const validLevels = resolveSupportedThinkingLevels(ctx.model);
290	        if (!isThinkingLevel(level) || !validLevels.includes(level)) {
291	          return textResult(
292	            `Invalid thinking level: ${level}. Valid levels: ${validLevels.join(", ")}.`,
293	          );
294	        }
295	
296	        const persist = params.persist ?? false;
297	        const currentLevel = state.currentLevel ?? pi.getThinkingLevel();
298	        if (currentLevel === level) {
299	          return textResult(`Thinking level is already ${level}; no change made.`);
300	        }
301	
302	        if (state.reasoningToolCallBackToBackById.get(toolCallId) ?? false) {
303	          return textResult(
304	            `Thinking level change skipped because the previous tool call was also ${state.config.toolName}. Reassess after another tool call or new user input.`,
305	          );
306	        }
307	
308	        const resetLevel =
309	          state.persistedLevel ?? (isThinkingLevel(currentLevel) ? currentLevel : undefined);
310	
311	        try {
312	          withSessionOnlyThinkingLevelChange(() => pi.setThinkingLevel(level));
313	        } catch (error) {
314	          return textResult(`Failed to set thinking level: ${errorMessage(error)}`);
315	        }
316	
317	        state.currentLevel = level;
318	        if (persist) {
319	          state.persistedLevel = level;
320	          delete state.temporaryResetLevel;
321	        } else if (resetLevel && resetLevel !== level) {
322	          state.temporaryResetLevel = resetLevel;
323	        } else {
324	          delete state.temporaryResetLevel;
325	        }
326	
327	        return textResult(`Thinking level set to ${level}`);
328	      },
329	    });
330	
331	    registerRuntimeHandlers();
332	  });
333	}

