  6	
  7	type Handler = (event: any, ctx: any) => any;
  8	
  9	const createPi = () => {
 10	  const handlers = new Map<string, Handler[]>();
 11	  const tools: any[] = [];
 12	  const pi = {
 13	    on: vi.fn((event: string, handler: Handler) => {
 14	      handlers.set(event, [...(handlers.get(event) ?? []), handler]);
 15	    }),
 16	    registerTool: vi.fn((tool: any) => {
 17	      tools.push(tool);
 18	    }),
 19	    getThinkingLevel: vi.fn(() => "medium"),
 20	    setThinkingLevel: vi.fn(),
 21	  };
 22	
 23	  const emit = async (event: string, payload: any, ctx: any) => {
 24	    let result: any;
 25	    for (const handler of handlers.get(event) ?? []) {
 26	      result = await handler(payload, ctx);
 27	    }
 28	    return result;
 29	  };
 30	
 31	  return { pi, tools, emit };
 32	};
 33	
 34	const createCtx = (overrides: Partial<any> = {}) => ({
 35	  cwd: "/tmp/project",
 36	  hasUI: true,
 37	  ui: { notify: vi.fn() },
 38	  model: undefined,
 39	  ...overrides,
 40	});
